#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <numpy/arrayobject.h>
#include <stdlib.h>
#include <string.h>

typedef void (*dgeev_fn)(char*, char*, long*, double*, long*, double*, double*,
                         double*, long*, double*, long*, double*, long*, long*);

static dgeev_fn dgeev_ptr = NULL;

static PyObject* set_dgeev(PyObject* self, PyObject* arg) {
    unsigned long long addr = PyLong_AsUnsignedLongLong(arg);
    if (PyErr_Occurred()) return NULL;
    dgeev_ptr = (dgeev_fn)(uintptr_t)addr;
    Py_RETURN_NONE;
}

static PyObject* dominant(PyObject* self, PyObject* arg) {
    if (dgeev_ptr == NULL) {
        PyErr_SetString(PyExc_RuntimeError, "dgeev pointer not set");
        return NULL;
    }
    PyArrayObject* A = (PyArrayObject*)PyArray_FROM_OTF(arg, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (A == NULL) return NULL;
    if (PyArray_NDIM(A) != 2 || PyArray_DIM(A,0) != PyArray_DIM(A,1)) {
        Py_DECREF(A);
        PyErr_SetString(PyExc_ValueError, "expected 2D square matrix");
        return NULL;
    }
    long n = (long)PyArray_DIM(A, 0);
    long nn = n, lda = n, ldvl = 1, ldvr = n;
    long lwork = 100 * n;
    if (lwork < 1) lwork = 1;
    long info = 0;
    double *a, *wr, *wi, *vr, *work;
    double stack_a[400], stack_wr[20], stack_wi[20], stack_vr[400], stack_work[2000];
    if (n <= 20) {
        a = stack_a; wr = stack_wr; wi = stack_wi; vr = stack_vr; work = stack_work;
    } else {
        a = (double*)malloc(sizeof(double)*n*n);
        wr = (double*)malloc(sizeof(double)*n);
        wi = (double*)malloc(sizeof(double)*n);
        vr = (double*)malloc(sizeof(double)*n*n);
        work = (double*)malloc(sizeof(double)*lwork);
        if (!a || !wr || !wi || !vr || !work) {
            free(a); free(wr); free(wi); free(vr); free(work);
            Py_DECREF(A);
            return PyErr_NoMemory();
        }
    }
    const double* src = (const double*)PyArray_DATA(A);
    /* input is C-contiguous; LAPACK wants column-major */
    for (long j = 0; j < n; ++j)
        for (long i = 0; i < n; ++i)
            a[j*n + i] = src[i*n + j];
    char jobvl = 'N', jobvr = 'V';
    dgeev_ptr(&jobvl, &jobvr, &nn, a, &lda, wr, wi, NULL, &ldvl, vr, &ldvr,
              work, &lwork, &info);
    Py_DECREF(A);
    if (info != 0) {
        if (n > 20) { free(a); free(wr); free(wi); free(vr); free(work); }
        PyErr_Format(PyExc_RuntimeError, "dgeev failed with info=%ld", info);
        return NULL;
    }
    long best = 0;
    double bestm = wr[0]*wr[0] + wi[0]*wi[0];
    for (long i = 1; i < n; ++i) {
        double m = wr[i]*wr[i] + wi[i]*wi[i];
        if (m > bestm) { bestm = m; best = i; }
    }
    npy_intp dims[1] = {n};
    PyObject* vec = PyArray_SimpleNew(1, dims, NPY_CDOUBLE);
    if (vec == NULL) {
        if (n > 20) { free(a); free(wr); free(wi); free(vr); free(work); }
        return NULL;
    }
    npy_cdouble* out = (npy_cdouble*)PyArray_DATA((PyArrayObject*)vec);
    double re, im;
    if (wi[best] == 0.0) {
        re = wr[best]; im = 0.0;
        for (long i = 0; i < n; ++i) {
            out[i].real = vr[i*n + best];
            out[i].imag = 0.0;
        }
    } else if (wi[best] > 0.0) {
        re = wr[best]; im = wi[best];
        for (long i = 0; i < n; ++i) {
            out[i].real = vr[i*n + best];
            out[i].imag = vr[i*n + best + 1];
        }
    } else {
        re = wr[best]; im = wi[best];
        for (long i = 0; i < n; ++i) {
            out[i].real = vr[i*n + best];
            out[i].imag = -vr[i*n + best + 1];
        }
    }
    if (n > 20) { free(a); free(wr); free(wi); free(vr); free(work); }
    npy_cdouble zval;
    zval.real = re; zval.imag = im;
    PyObject* val = PyArray_Scalar(&zval, PyArray_DESCR((PyArrayObject*)vec), vec);
    if (val == NULL) { Py_DECREF(vec); return NULL; }
    PyObject* result = PyTuple_New(2);
    if (result == NULL) { Py_DECREF(val); Py_DECREF(vec); return NULL; }
    PyTuple_SET_ITEM(result, 0, val);
    PyTuple_SET_ITEM(result, 1, vec);
    return result;
}

static PyMethodDef methods[] = {
    {"dominant", dominant, METH_O, "dominant eigenpair"},
    {"set_dgeev", set_dgeev, METH_O, "set dgeev address"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "_eigen", NULL, -1, methods
};

PyMODINIT_FUNC PyInit__eigen(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
